namespace StdbModule;

public static partial class SpanishQuotes
{
    public static class MigueldeUnamuno
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "A veces, el silencio es la peor mentira.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Cada nuevo amigo que ganamos en la carrera de la vida nos perfecciona y enriquece más aún por lo que de nosotros mismos nos descubre, que por lo que de él mismo nos da.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Con maderas de recuerdos armamos las esperanzas.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "¿De cuándo acá ha de ser el autor de un libro el que mejor lo entienda?", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Déjales con lo que llaman sus ideas, cuando en realidad son ellos de las ideas que llaman suyas.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "El cielo de la fama no es muy grande y cuantos más en él entren a su cama, a menos tocan cada uno de ellos.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "El escritor sólo puede interesar a la humanidad cuando en sus obras se interesa por la humanidad.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "El hombre es un producto social y la sociedad debe impedir que se pierda para ella.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "El modo de dar una vez en el clavo es dar cien veces en la herradura.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "El nacionalismo es la chifladura de exaltados echados a perder por indigestiones de mala historia.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "El nombre es, en cierto sentido, la cosa misma; dar nombre a las cosas es conocerlas y apropiárselas; el nombramiento es el acto de posesión espiritual.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "El periodismo mata la literatura.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "El tener que ganarse la vida perturba la serenidad del espíritu.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Es detestable esa avaricia espiritual que tienen los que sabiendo algo, no procuran la transmisión de esos conocimientos.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Es en el aspecto religioso donde hay que ir a buscar lo más típico y lo más radical de un pueblo.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Fe sin dudas es fe muerta.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Han sido siempre poetas, hombres enamorados de la gloria, los que han cantado la vanidad de ella.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Hasta cuando la mujer tiene menos inteligencia, tiene más sentido común que el hombre.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Hasta un ateo necesita a Dios para negarlo.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Hay que buscar la verdad y no la razón de las cosas. Y la verdad se busca con humildad.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "He dicho alguna vez, con escándalo acaso de ciertos pedantes, que la verdadera universidad popular española han sido el café y la plaza pública.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Hubo árboles antes de que hubiera libros, y acaso cuando acaben los libros continúen los árboles. Y acaso llegue la humanidad a un grado de cultura tal que no necesite ya de libros, pero siempre necesitará de árboles, y entonces abonará los árboles con libros.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "La conciencia es una enfermedad.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "La envidia es mil veces más terrible que el hambre, porque es hambre espiritual.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "La fe se mantiene resolviendo dudas y volviendo a resolver las que den la resolución de las anteriores.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "La felicidad es una cosa que se vive y se siente, no una cosa que se razona y se define.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "La guerra ha sido siempre un factor de progreso; por ella es como aprenden a conocerse y quererse vencedores y vencidos. El progreso consiste en el cambio.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "La humildad consiste en transigir con la mentira.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "La libertad es un bien común y, mientras no participen todos de ella, no serán libres los que se creen tales.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "La opresión, una mentecatada. Hablar de nacionalidades oprimidas —perdonadme la fuerza, la dureza de la expresión— es sencillamente una mentecatada; no ha habido nunca semejante opresión, y lo demás es envenenar la Historia y falsearla.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "La peor intolerancia es la de eso que llaman razón.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "La sangre de mi espíritu es mi lengua. Y mi patria es allí donde resuena.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "La última y definitiva justicia es el perdón.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "La vida del hombre sobre la tierra es combate, y combate primero y ante todo consigo mismo.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "La vida es duda, y la fe sin la duda es sólo muerte.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "La vida no es sueño. El más vigoroso tacto espiritual es la necesidad de persistencia en una forma u otra. El anhelo de extenderse en tiempo y en espacio.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Lo que cansa y se estudia a disgusto, se aprende mal.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Lo que no se sabe expresar no se sabe.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Los que reniegan de Dios es por desesperación de no encontrarlo.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Los seres humanos gritan para no oirse.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Me ahogo, me ahogo, me ahogo en este albañal y me duele España en el cogollo del corazón.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Me cago en el vapor, la electricidad y en los sueros inyectados.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Mi divisa es: veritas prius pace, primero la verdad que la paz. Es mejor verdad con guerra que mentira con paz.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Miremos más que somos padres de nuestro porvenir que hijos de nuestro pasado.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "No caben, en punto a lenguaje, vinos nuevos en viejos odres.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "No des a nadie lo que te pida, sino lo que entiendes que necesita; y soporta luego su ingratitud.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "No nos molestan aquellos defectos que nosotros no tenemos.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "No sé de qué se trata, pero me opongo.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Nuestra sátira, nuestro sarcasmo, se parece más al humour inglés que no a la ironía francesa.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Obra de modo que merezcas a tu propio juicio y a juicio de los demás la eternidad, que te hagas insustituible, que no merezcas morir.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Que al fuerte siempre la piedad le inspira.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Siento el pensamiento, pienso el sentimiento.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Soberbia y refinada mediocridad es abstenerse de obrar por no exponerse a la crítica.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Todo acto de bondad es una demostración de poderío.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Tu desconfianza me inquieta y tu silencio me ofende.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Una de las ventajas de no ser feliz es que se puede desear la felicidad.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Un amor puede vivir de recuerdos. El odio necesita realidades presentes.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Un pedante es un estúpido adulterado por el estudio.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Venceréis pero no convenceréis.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Y hay que viajar [...], por topofobia, para huir de cada lugar, no buscando aquel a que va, sino escapándose de aquel de donde parte.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Yo no aseguro ni puedo asegurar que hay otra vida; no estoy convencido de que la haya; pero no me cabe en la cabeza que un hombre de verdad no sólo se resigne a gozar más que de esta vida, sino que renuncie a la otra, y hasta la rechace.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Yo tengo tan buena memoria, como buen olvido.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Y pasan los días sin que pase nada, y todo queda pues pasa todo.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "En este libro tan profundamente anticristiano leí aquello del programa de 1903 de la Action Francaise que \"un verdadero nacionalista pone la patria ante todo y, por ende, concibe, trata y resuelve todas las cuestiones políticas en su relación con el interés nacional\". Al leer lo cual me acordé de aquello de \"mi reino no es de este mundo\", y pensé que para un verdadero cristiano —si es que un verdadero cristiano es posible en la vida civil— toda cuestión política o lo que sea, debe concebirse, tratarse o resolverse en su relación con el interés individual de la salvación eterna, de la eternidad. ¿Y si perece la patria? La patria de un cristiano no es de este mundo. Un cristiano debe sacrificar la patria a la verdad.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Mi situación económica se ha resuelto gracias a los americanos. Entre La Nación, de Buenos Aires —mi tribuna hoy—; Caras y Caretas, también de Buenos Aires, y el Diario Ilustrado, de Santiago de Chile, me han emancipado, ¡Gracias a Dios!, de la prensa española. Allí pagan triple que aquí y agradecen quíntuple.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "La libertad no es un estado sino un proceso; sólo el que sabe es libre, y más libre el que más sabe. Sólo la cultura da libertad. No proclaméis la libertad de volar, sino dad alas; no la de pensar, sino dad pensamientos. La libertad que hay que dar al pueblo es la cultura. Sólo la imposición de la cultura lo hará dueño de sí mismo, que es en lo que la democracia estriba.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Ni, pues, el anhelo vital de inmortalidad humana halla confirmación racional, ni tampoco la razón nos da aliciente y consuelo de vida y verdadera finalidad a ésta. Mas he aquí que en el fondo del abismo se encuentran la desesperación sentimental y volitiva y el escepticismo racional frente a frente, y se abrazan como hermanos. Y va a ser de este abrazo, un abrazo trágico, es decir, entrañadamente amoroso de donde va a brotar el manantial de la vida, de una vida seria y terrible.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Una de las más fecundas tareas que a los escritores en lengua castellana se nos abren es la de forjar un idioma digno de los varios y dilatados países en que se ha de hablar, y capaz de traducir las diversas impresiones e ideas de tan diversas naciones. Y el viejo castellano, acompasado y enfático, lengua de oradores más que de escritores —pues en España los más de estos últimos son oradores por escrito— el viejo castellano necesita refundición. Necesita para europeizarse a la moderna más ligereza y más precisión a la vez... Revolucionar la lengua es la más honda revolución que puede hacerse. Sin ella, la revolución en las ideas no es más que aparente.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Creer en Dios es, en cierto modo, crearle.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "La fe es la fuente de la realidad, porque es la vida; creer es crear.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "El que tiene fe en sí mismo no necesita que los demás crean en él.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Es el amor hijo del engaño y padre del desengaño.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Hay quien vive del aire sin conocerlo.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "El cristianismo es apolítico.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "¿Y qué es amor? ¿Quién definió el amor? Amor definido deja de serlo.", Author = "Miguel de Unamuno" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Nada hay más ambiguo que eso que se llama realismo en el arte literario. Porque, ¿qué realidad es la de ese realismo? ", Author = "Miguel de Unamuno" },
        };
    }
}